-- Keep the provider binding paired and allow one explicit Dodo environment.
-- Existing test bindings stay test-bound; runtime rejects a mode switch.
ALTER TABLE "SystemControl"
  DROP CONSTRAINT "SystemControl_dodo_binding_check";

ALTER TABLE "SystemControl"
  ADD CONSTRAINT "SystemControl_dodo_binding_check" CHECK (
    ("dodoEnvironment" IS NULL AND "dodoBusinessId" IS NULL) OR
    ("dodoEnvironment" IN ('test_mode', 'live_mode') AND
      "dodoBusinessId" IS NOT NULL AND length(btrim("dodoBusinessId")) > 0)
  );
